$imgid = externimg_sideload($imgs[$i], $filename, $post_id);
$imgpath = wp_get_attachment_url($imgid);
if (!is_wp_error($imgpath)) {
if ($l=='custtag') {
add_post_meta($post_id, $k, $imgs[$i], false);
} else {
